<script setup lang="ts">
import {computed,ref,onBeforeUnmount,watch,reactive} from 'vue'
import DetailWorkspace from '@/components/layout/DetailWorkspace.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import {protectedChannel} from './channelActions'
import UiButton from '@/components/ui/UiButton.vue'
import UiSelectField from '@/components/ui/UiSelectField.vue'
import ModelRuleFields from './ModelRuleFields.vue'
import NewChannelDialog from './NewChannelDialog.vue'
import NodePicker from './NodePicker.vue'
import {useNodeMeasurements} from './useNodeMeasurements'
import type {DiscoveryKindV2} from './api-v2'
import ChannelModelTable from './ChannelModelTable.vue'
import {useModelsV2Store} from './store-v2'
import {useModalStore} from '@/app/modal/store'
import {channelNameErrorV2} from './channelRename'
import type {ChannelV2,EffectiveModelV2,ChannelIntentV2,ModelEditV2,ModelSelectionV2,RulesV2} from './api-v2'
import type {ChannelPolicy,ModelPolicy,ModelProjection,TemplateRef} from './api'
import type {ModelRowsState} from './modelRows'
import type {StatusTone} from '@/lib/saveStates'
const props=defineProps<{channel:ChannelV2|ChannelPolicy;effective?:readonly EffectiveModelV2[];channels?:readonly (ChannelV2|ChannelPolicy)[];busy?:boolean;templates?:readonly unknown[];existing?:boolean;globalRefs?:TemplateRef[];projection?:ModelProjection[];projectionBusy?:boolean;projectionError?:string;policy?:ModelPolicy;rowState?:ModelRowsState;navigation?:{collapsed:boolean;activeId:string};saveDisabled?:boolean;dirty?:boolean;saveStatus?:string;saveTone?:StatusTone;activeCount?:number;viewState?:{search:string;selectedOnly:boolean;family:string}}>()
const emit=defineEmits<{close:[];save:[];switch:[id:string];intent:[value:ChannelIntentV2];edit:[value:ModelEditV2]}>()
const store=useModelsV2Store(),editConnection=ref(false),query=ref(''),selectedOnly=ref(false),family=ref(''),keyVisible=ref(false),keyView=ref(''),keySource=ref(''),keyError=ref(''),keyLoading=ref(false),keyReplacement=ref(''),keyAction=ref<'unchanged'|'replace'|'clear'>('unchanged'),manualOpen=ref(false),manualId=ref(''),manualError=ref(''),navCollapsed=ref(false),navActive=ref('channel-config')
const nodeKind=ref<DiscoveryKindV2|''>(''),nodeDialog=ref(false)
const measurement=reactive(useNodeMeasurements(()=>props.channel,()=>'',{expected:()=>store.file?.draft?.base??null,discoveryKind:()=>nodeKind.value,enabled:()=>store.channelCapabilities.measure}))
const channel=computed(()=>('models'in props.channel?props.channel:null) as ChannelV2|null)
const nameError=computed(()=>channelNameErrorV2(props.channel.label,props.channel.id,props.channels??store.channels))
const selectedCount=computed(()=>!channel.value?0:channel.value.selection.mode==='all'?channel.value.models.length:channel.value.selection.mode==='whitelist'?channel.value.selection.models.length:0)
let keySequence=0
async function inspectKey(){if(!channel.value||keyLoading.value)return;if(keyVisible.value){keyVisible.value=false;keyView.value='';return}const sequence=++keySequence,id=channel.value.id;keyLoading.value=true;keyError.value='';try{const result=await store.viewCredential(id);if(sequence!==keySequence||props.channel.id!==id)return;keySource.value=result.source;if(!result.viewable){keyError.value=result.configured?'已配置；此来源暂无法显示明文。':'尚未配置 Key。';return}keyView.value=result.value;keyVisible.value=true}catch(cause){if(sequence===keySequence)keyError.value=cause instanceof Error?cause.message:'Key 查看未完成。'}finally{if(sequence===keySequence)keyLoading.value=false}}
function replaceKey(event:Event){keyReplacement.value=(event.target as HTMLInputElement).value;keyAction.value=keyReplacement.value?'replace':'unchanged';store.setKeyBuffer(props.channel.id,keyReplacement.value?{action:'replace',value:keyReplacement.value}:null);keyError.value=''}
function back(){emit('close')}
function clearKey(){keyAction.value='clear';keyReplacement.value='';keyView.value='';keyVisible.value=false;store.setKeyBuffer(props.channel.id,{action:'clear'});keyError.value=''}
function saveChannel(){if(nameError.value)return;if(keyAction.value==='replace'&&(!keyReplacement.value||keyReplacement.value.length>8192||/[\r\n]/.test(keyReplacement.value))){keyError.value='请输入有效 API Key。';return}emit('save')}
onBeforeUnmount(()=>{keySequence++;keyView.value='';keyReplacement.value=''})
watch(()=>[props.channel.id,store.credentialInputRevision,store.file?.sourceDigest,store.file?.libraryDigest,store.file?.rootRevision],()=>{keySequence++;keyLoading.value=false;keySource.value='';keyError.value='';keyView.value='';keyReplacement.value='';const buffer=store.keyBuffer(props.channel.id);keyReplacement.value=buffer?.value??'';keyAction.value=buffer?.action??'unchanged';keyVisible.value=false},{immediate:true})
const protectedSource=computed(()=>protectedChannel(props.channel))
const sections=[{id:'channel-config',label:'渠道配置'},{id:'channel-nodes',label:'服务节点'},{id:'channel-defaults',label:'模型默认'},{id:'channel-models',label:'模型列表'}]
async function addManual(){if(!channel.value||props.busy)return;const raw=manualId.value;if(!raw||raw.trim()!==raw||new TextEncoder().encode(raw).length>2048||/[\u0000-\u001f\u007f]/.test(raw)){manualError.value='请输入完整且不含首尾空白或控制字符的精确模型 ID。';return}if(channel.value.models.some(m=>m.rawModelId===raw)){manualError.value='此精确 ID 已存在。';return}try{await store.stageConnection({channelId:channel.value.id,kind:'edit_connection',label:channel.value.label,nodes:channel.value.connection.nodes,activeNodeId:channel.value.connection.activeNodeId,authMode:channel.value.connection.authMode==='none'?'none':'key',selectedModelIds:channel.value.selection.mode==='all'?[...channel.value.models.map(m=>m.rawModelId),raw]:channel.value.selection.mode==='whitelist'?[...channel.value.selection.models]:[],modelOrder:[...channel.value.modelOrder,raw],modelLabels:{[raw]:raw},discoveryReadId:null},{action:'unchanged'});manualOpen.value=false;manualId.value=''}catch(cause){manualError.value=cause instanceof Error?cause.message:'添加未完成，精确 ID 保留。'}}
function confirmSelection(value:ModelSelectionV2){const baseline=JSON.stringify(channel.value),selection=value;useModalStore().open({title:'调整模型公开范围',body:selection.mode==='all'?'全部当前与以后发现模型将公开，保存仍核对实际参数与预算。':selection.mode==='none'?'当前与以后模型将隐藏，模型配置、身份及顺序保留。':'改为明确白名单，保留当前已选择的原始 ID。',confirmLabel:'确认范围',onConfirm:()=>{if(props.busy||JSON.stringify(channel.value)!==baseline){store.fileError='范围确认已过期，当前输入保持。';return}emit('intent',{kind:'set_selection',channelId:props.channel.id,selection})}})}
function rename(event:Event){if(props.busy||protectedSource.value)return;emit('intent',{kind:'rename',channelId:props.channel.id,name:(event.target as HTMLInputElement).value})}
function selection(value:ModelSelectionV2){emit('intent',{kind:'set_selection',channelId:props.channel.id,selection:value})}
function setReferences(templateId:string,revisionId:string){if(!channel.value||!store.channelCapabilities.templateRefs)return;const references=channel.value.templateRefs.filter(r=>r.templateId!==templateId);if(revisionId){const revision=store.file?.library.templates.find(t=>t.id===templateId)?.revisions.find(r=>r.id===revisionId);if(!revision)return;references.push({templateId,revisionId,digest:revision.digest})}emit('intent',{kind:'set_template_refs',channelId:channel.value.id,references})}
function channelRules(rules:RulesV2){if(channel.value&&store.channelCapabilities.defaults)emit('intent',{kind:'set_defaults',channelId:channel.value.id,rules})}
function familyRules(templateId:string,rules:RulesV2){if(channel.value&&store.channelCapabilities.defaults)emit('intent',{kind:'set_family_defaults',channelId:channel.value.id,templateId,rules})}
</script>
<template>
  <section class="channel-editor-v2">

    <p v-if="!channel" role="alert" class="model-error">此渠道不是新版格式，请重新读取；旧原件没有被转换。</p>
    <DetailWorkspace v-else label="渠道导航" :sections="sections" v-model:collapsed="navCollapsed" v-model:active-id="navActive">
      <template #header><UiButton size="sm" variant="ghost" aria-label="返回渠道列表" @click="back">返回渠道列表</UiButton><h2>{{channel!.label}}</h2><span role="status" data-status-scope="current-channel" title="当前渠道的保存状态">{{saveStatus??(busy?'正在处理':dirty?'未保存修改':'未修改')}}</span><span>{{channel!.connection.enabled?'已启用':'已停用'}} · 已选 {{selectedCount}} / {{channel!.models.length}}</span></template>
      <template #primary="{collapsed}"><UiButton variant="primary" aria-label="保存渠道草稿" title="保存当前渠道，成功后返回渠道列表；其它渠道修改保留" data-save-scope="current-channel" :disabled="busy||saveDisabled||dirty===false||!!nameError||protectedSource" @click="saveChannel"><svg class="channel-save-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M5 3h12l4 4v14H3V3zM7 3v6h10V3M7 21v-8h10v8"/></svg><span v-if="!collapsed">{{store.channelCapabilities.scopedSave?'保存当前渠道':'保存当前草稿'}}</span></UiButton></template>
      <section id="channel-config" tabindex="-1"><h3>渠道与连接</h3><label>渠道名称<input class="input" aria-label="渠道名称" :value="channel.label" :disabled="busy||protectedSource" maxlength="80" @input="rename" /></label><p v-if="nameError" role="alert" class="model-error">{{nameError}}</p><p class="model-muted">保存由同一事务处理真实名称、运行键及引用；不会改写原始模型 ID 或凭据。保存后需重启 Codex 生效。</p><label class="model-inline"><input type="checkbox" aria-label="启用渠道" :checked="channel.connection.enabled" :disabled="busy||protectedSource" @change="emit('intent',{kind:'set_enabled',channelId:channel.id,enabled:($event.target as HTMLInputElement).checked})" />启用渠道</label>
        <dl><dt>认证方式</dt><dd>{{channel.connection.authMode==='none'?'无需认证':'API Key / 实际来源'}}</dd><dt>凭据</dt><dd>{{channel.connection.credentialRef?'已配置（不会在页面读取明文）':'未配置或由实际受控来源提供'}}</dd></dl>
        <div class="model-columns"><label>API Key<input class="input" aria-label="渠道替换API Key" type="password" :value="keyReplacement" :disabled="busy||protectedSource||!store.channelCapabilities.credential" placeholder="输入新 Key，留空不代表清空" autocomplete="new-password" @input="replaceKey" /></label><label v-if="keyVisible">已保存 Key<input class="input" aria-label="已保存渠道Key" :value="keyView" readonly /></label></div>
        <div class="model-inline"><UiButton size="sm" :disabled="busy||protectedSource||keyLoading||!store.channelCapabilities.credential" @click="inspectKey">{{keyVisible?'隐藏 Key':'查看已保存 Key'}}</UiButton><UiButton size="sm" :disabled="busy||protectedSource||!store.channelCapabilities.credential" @click="clearKey">明确清空 Key</UiButton></div><p v-if="keyAction!=='unchanged'" role="status">{{keyAction==='clear'?'保存后明确清空 Key，认证方式保持。':'保存后替换 Key，未发送到模型接口。'}}</p><p v-if="keySource" class="model-muted">Key 来源：{{keySource}}</p><p v-if="keyError" role="alert" class="model-error">{{keyError}}</p><p v-if="!store.channelCapabilities.credential" class="model-muted">Key 写入口尚未就绪，现有认证状态保持。</p>
        <UiButton :disabled="busy||protectedSource" @click="editConnection=true">编辑渠道连接</UiButton>
      </section>
      <section id="channel-nodes" tabindex="-1"><div class="model-field-title"><h3>服务节点</h3><UiButton :disabled="busy||!channel.connection.nodes.length" @click="nodeDialog=true">检测服务节点</UiButton></div><ul><li v-for="node in channel.connection.nodes" :key="node.id"><strong>{{node.name}}</strong><span v-if="node.id===channel.connection.activeNodeId"> · 当前节点</span><code>{{node.url}}</code></li></ul><p class="model-muted">编辑连接时完整保留节点集合。清单获取方式只在本次读取选择，不保存为请求协议。</p></section>
      <details id="channel-defaults"><summary>非协议渠道默认与族设置</summary><p class="model-muted">协议不在渠道层定义。编辑只发明确默认/族设置意图，来源事实与模型人工覆盖分别保留。</p><p v-if="!store.channelCapabilities.defaults" class="model-muted">设置写入口尚未就绪，现有值保留供查看。</p><ModelRuleFields :model-value="channel.defaults" hide-protocol :disabled="busy||!store.channelCapabilities.defaults" @update:model-value="channelRules" /><section v-for="(rules,id) in channel.familyOverrides" :key="id"><h4>{{store.file?.library.templates.find(t=>t.id===id)?.label??id}}</h4><ModelRuleFields :model-value="rules" hide-protocol :disabled="busy||!store.channelCapabilities.defaults" @update:model-value="familyRules(String(id),$event)" /></section><div class="model-inline"><UiSelectField v-model="family" label="添加族默认设置" :disabled="busy||!store.channelCapabilities.defaults" :options="[{value:'',label:'选择模型族'},...(store.file?.library.templates??[]).filter(t=>!channel!.familyOverrides[t.id]).map(t=>({value:t.id,label:t.label}))]" /><UiButton :disabled="busy||!family||!store.channelCapabilities.defaults" @click="familyRules(family,{protocol:{mode:'inherit'},contextWindow:{mode:'inherit'},inputModalities:{mode:'inherit'},reasoningEfforts:{mode:'inherit'},defaultEffort:{mode:'inherit'},fast:{mode:'inherit'}})">添加族设置</UiButton></div></details>
      <details><summary>明确的模版候选版本</summary><p class="model-muted">只选择确切已保存版本；候选引用变化不后台重选自动匹配，下一次明确读取再评估。</p><label v-for="template in store.file?.library.templates??[]" :key="template.id">{{template.label}}<UiSelectField :model-value="channel.templateRefs.find(r=>r.templateId===template.id)?.revisionId??''" :disabled="busy||!store.channelCapabilities.templateRefs" :label="template.label+'候选版本'" :options="[{value:'',label:'未指定候选'},...template.revisions.map(r=>({value:r.id,label:r.createdAt+' · '+r.id.slice(0,8)}))]" @update:model-value="setReferences(template.id,$event)" /></label><p v-for="reference in channel.templateRefs.filter(r=>!store.file?.library.templates.some(t=>t.id===r.templateId&&t.revisions.some(v=>v.id===r.revisionId)))" :key="reference.templateId" role="alert">精确候选依赖缺失：{{reference.templateId}} / {{reference.revisionId}}，引用保持。</p></details>
      <section id="channel-models" tabindex="-1"><div class="model-field-title"><h3>模型列表</h3><UiButton :disabled="busy||protectedSource" @click="manualError='';manualOpen=true">手动添加精确ID</UiButton></div><div class="model-inline"><input v-model="query" class="input" type="search" aria-label="渠道模型搜索" placeholder="搜索原始模型 ID / 名称" /><label><input v-model="selectedOnly" type="checkbox" />仅已选</label><UiSelectField :model-value="channel.selection.mode" :disabled="busy" label="模型公开范围" :options="[{value:'all',label:'全部模型（含以后发现）'},{value:'none',label:'全部隐藏'},{value:'whitelist',label:'明确白名单'}]" @update:model-value="confirmSelection($event==='whitelist'?{mode:'whitelist',models:channel.models.filter(m=>channel!.selection.mode==='all'||channel!.selection.mode==='whitelist'&&channel!.selection.models.includes(m.rawModelId)).map(m=>m.rawModelId)}:{mode:$event as 'all'|'none'})" /></div><ChannelModelTable :channel="channel" :effective="effective" :query="query" :selected-only="selectedOnly" :disabled="busy||protectedSource" @edit="emit('edit',$event)" @intent="emit('intent',$event)" @selection="selection" @order="emit('intent',{kind:'set_order',channelId:channel.id,rawModelIds:$event})" /></section>
      <NewChannelDialog v-if="editConnection" :original="channel" @close="editConnection=false" @added="editConnection=false" />
      <UiDialog :open="nodeDialog" title="服务节点检测" wide @close="nodeDialog=false"><UiSelectField v-model="nodeKind" label="本次节点清单获取方式" :disabled="!!measurement.run" :options="[{value:'',label:'请选择本次获取方式'},{value:'openai_list',label:'兼容模型清单'},{value:'anthropic_list',label:'Anthropic 模型清单'},{value:'google_list',label:'Google 模型清单'},{value:'ollama_list',label:'Ollama 模型清单'}]" /><p class="model-muted">只读取节点 ID 对应的可信地址与已认可凭据，不自动切换节点；本次方式不保存为渠道协议。</p><p v-if="!store.channelCapabilities.measure" role="status">检测服务尚未就绪，现有节点可查看，未发送请求。</p><NodePicker :nodes="channel.connection.nodes" :active-id="channel.connection.activeNodeId" readonly :selection-disabled="!store.channelCapabilities.activeNode||busy" :measurement-disabled="!store.channelCapabilities.measure||!nodeKind||busy" :measuring="!!measurement.run" :pending="measurement.pending" :results="measurement.results" :error="measurement.error" :stopped="measurement.stopped" @measure="measurement.measure" @stop="measurement.stop" @update:active-id="emit('intent',{kind:'set_active_node',channelId:channel.id,nodeId:$event})" /></UiDialog>
      <UiDialog :open="manualOpen" title="添加精确模型 ID" :busy="store.fileBusy" @close="manualOpen=false"><label>原始模型 ID<input v-model="manualId" class="input" aria-label="新增精确模型ID" :disabled="store.fileBusy" /></label><p>只加入服务端草稿，保持原始 ID，不根据名称补能力或协议；保存配置后生效。</p><p v-if="manualError" role="alert" class="model-error">{{manualError}}</p><template #actions="{close}"><UiButton :disabled="store.fileBusy" @click="close">取消</UiButton><UiButton variant="primary" :disabled="store.fileBusy||!manualId" @click="addManual">确认加入草稿</UiButton></template></UiDialog>
    </DetailWorkspace>
  </section>
</template>
<style scoped>
.channel-save-icon{width:16px;height:16px;flex:none}.channel-editor-v2{display:grid;gap:var(--space-5);min-width:0}.channel-editor-v2 h2{font-size:var(--text-title)}.channel-editor-v2 h3{font-size:var(--text-body)}.channel-editor-v2 label{display:grid;gap:var(--space-2);min-width:0}.channel-editor-v2 input{min-width:0}.channel-editor-v2 .model-inline label{display:flex;align-items:center}.channel-editor-v2 code{display:block;overflow-wrap:anywhere}.channel-editor-v2 dl{display:grid;grid-template-columns:auto minmax(0,1fr);gap:var(--space-2)}.channel-editor-v2 dd{margin:0;overflow-wrap:anywhere}
</style>
